insert into public.landmarks (id, name, category, district, latitude, longitude, image_url, admission_fee, rating, visit_count, estimated_visit_minutes, visiting_hours, story) values
  ('magellans-cross', 'Magellan''s Cross', 'monument', 'Cebu City (Downtown)', 10.29365, 123.90199, '/landmarks/magellan.jpg', 0, 4.8, 0, 20, '8:00 AM - 7:00 PM', '{"about":"A Christian cross planted by Ferdinand Magellan’s expedition when it arrived in Cebu in 1521. It is housed in a small octagonal chapel beside the Basilica del Santo Niño.","significance":"It marks the beginning of Christianity in the Philippines, linked to the baptism of Rajah Humabon, his wife and their followers in April 1521.","architecture":"The kiosk-style chapel has a painted ceiling depicting the planting of the cross. The original cross is said to be encased in tindalo wood to protect it.","trivia":"Many visitors once chipped pieces off the cross believing they had healing powers, which is one reason it was encased."}'::jsonb),
  ('basilica-santo-nino', 'Basilica Minore del Santo Niño', 'church', 'Cebu City (Downtown)', 10.29433, 123.90189, '/landmarks/basilica.jpg', 0, 4.9, 0, 45, '6:00 AM - 8:00 PM', '{"about":"One of the oldest churches in the Philippines, home to the image of the Santo Niño de Cebu, the Holy Child given by Magellan in 1521.","significance":"It is the center of the Sinulog festival held every January and was elevated to a minor basilica in 1965.","architecture":"The present stone church dates from the 18th century and blends Romanesque and Baroque elements, with a bell tower rebuilt after the 2013 Bohol earthquake.","trivia":"The Santo Niño image was reportedly found intact in a burned house in 1565 by soldiers of Miguel López de Legazpi."}'::jsonb),
  ('fort-san-pedro', 'Fort San Pedro', 'fort', 'Cebu City (Pier Area)', 10.29236, 123.90581, '/landmarks/fort.jpg', 30, 4.7, 0, 60, '8:00 AM - 7:00 PM', '{"about":"A triangular military fort near the Cebu port, started in 1565 under Miguel López de Legazpi.","significance":"It is considered the oldest and smallest triangular bastion fort in the country and served as the nucleus of the first Spanish settlement.","architecture":"Built of coral stone, it has two sides facing the sea and one facing land, with bastions named La Concepción, Ignacio de Loyola and San Miguel.","trivia":"Over the centuries it has served as a stronghold, an American barracks, a school, a Japanese prison camp during World War II and a zoo."}'::jsonb),
  ('yap-sandiego-house', 'Yap-Sandiego Ancestral House', 'heritage_house', 'Parian, Cebu City', 10.29598, 123.90503, '/landmarks/yap.jpg', 50, 4.5, 0, 30, '9:00 AM - 6:00 PM', '{"about":"A residence in the old Parian district built in the late 1600s by a Chinese merchant family, and among the oldest houses in the country.","significance":"It reflects the life of Cebu’s Chinese mestizo merchant class during the Spanish colonial period.","architecture":"Coral stone walls bound with egg whites support an upper floor of hardwood, topped with clay roof tiles.","trivia":"The house is still privately owned by descendants of the family, who opened it to visitors as a living museum."}'::jsonb),
  ('casa-gorordo', 'Casa Gorordo Museum', 'museum', 'Parian, Cebu City', 10.29638, 123.90432, '/landmarks/casa.jpg', 120, 4.6, 0, 45, '9:00 AM - 5:00 PM (closed Mondays)', '{"about":"A 19th-century house that was home to the Gorordo family, including Juan Gorordo, the first Filipino bishop of Cebu.","significance":"Now a museum, it shows domestic life in Cebu from the late Spanish to the early American period.","architecture":"A classic bahay na bato: coral stone lower floor and an upper floor of molave wood with capiz shell windows.","trivia":"It was declared a National Historical Landmark and is managed by the Ramon Aboitiz Foundation."}'::jsonb),
  ('heritage-of-cebu-monument', 'Heritage of Cebu Monument', 'monument', 'Parian, Cebu City', 10.29591, 123.90391, '/landmarks/heritage.jpg', 0, 4.2, 0, 15, 'Open daily', '{"about":"A sculptural tableau in Plaza Parian that depicts key events and figures in Cebu’s history.","significance":"It condenses centuries of Cebuano history, from pre-colonial trade to the Spanish era and beyond, into one public artwork.","architecture":"Made of concrete, bronze, brass and steel, the work by sculptor Eduardo Castrillo was completed in 2000.","trivia":"Look for scenes of Magellan’s arrival, the Battle of Mactan, and the Santo Niño among the figures."}'::jsonb),
  ('museo-sugbo', 'Museo Sugbo', 'museum', 'Cebu City (Downtown)', 10.30128, 123.90685, '/landmarks/museo.jpg', 75, 4.5, 0, 60, '9:00 AM - 6:00 PM (closed Mondays)', '{"about":"The Cebu provincial museum, with galleries on Cebu’s history from pre-colonial times to the modern era.","significance":"The building itself is historic: it was the Carcel de Cebu, the provincial jail, built in the 1870s.","architecture":"Coral stone prison walls and cell blocks now house exhibit halls arranged around a central courtyard.","trivia":"During World War II the jail was used by the Japanese forces, and later served again as the provincial jail."}'::jsonb),
  ('taoist-temple', 'Cebu Taoist Temple', 'temple', 'Beverly Hills, Lahug', 10.33845, 123.89075, null, 0, 4.6, 0, 45, '6:00 AM - 5:00 PM', '{"about":"A hillside temple built in 1972 by Cebu’s Chinese community, overlooking the city.","significance":"It is a center of worship for followers of Taoism and reflects the long presence of Chinese Filipinos in Cebu.","architecture":"Multi-tiered pagoda roofs, dragon sculptures and a replica of the Great Wall of China lead up to the main temple.","trivia":"Visitors climb 81 steps to reach the temple, the number of chapters in the Tao Te Ching."}'::jsonb)
insert into public.quests (id, title, description, badge_name) values
  ('spanish-colonial-trail', 'Spanish Colonial Heritage Trail', 'Walk the first Spanish settlement, from the fort by the sea to the oldest church.', 'Magellan''s Chronicler'),
